@Component("deviceVendor-handler")
@ProcessingGroup("deviceVendor-processing-group")
public class DeviceVendorEventHandler {
	
	// core constructor
	DeviceVendorEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateDeviceVendorEvent
     */
    @EventHandler
    public void handle( CreateDeviceVendorEvent event) {
        entityManager.persist(new DeviceVendor(event.getDeviceVendorId(), event.getName(), event.getLegalName(), event.getHeadquartersCountry(), event.getWebsite(), event.getDeviceModels(), event.getFirmwareReleases(), event.getHardwareModules()));
    }

    /*
     * @param	event UpdateDeviceVendorEvent
     */
    @EventHandler
    public DeviceVendor handle( UpdateDeviceVendorEvent event) {
    	entityManager.merge(new DeviceVendor(event.getDeviceVendorId(), event.getName(), event.getLegalName(), event.getHeadquartersCountry(), event.getWebsite(), event.getDeviceModels(), event.getFirmwareReleases(), event.getHardwareModules()));
    }
    
    /*
     * @param	event DeleteDeviceVendorEvent
     */
    @EventHandler
    public void on( DeleteDeviceVendorEvent event) {
    	DeviceVendor entity = new DeviceVendor();
   
    	// ------------------------------------------
    	// apply the DeviceVendorId
    	// ------------------------------------------
    	entity.setDeviceVendorId( event.getDeviceVendorId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final DeviceVendorRepository deviceVendorEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(DeviceVendorEventHandler.class.getName());

}
